"""Meridian CRM RBAC permission check migration."""


def can(
    user: dict,
    action: str,
    object: str,
    record: dict,
    role_rows: list[dict],
) -> bool:
    """Return whether *user* may perform *action* on *record*.

    Permission rows are required for every grant, including ADMIN.  ADMIN
    bypasses only row-level scope evaluation.
    """
    role_id = user.get("ROLE_ID", "")
    user_id = user.get("USR_ID", "")
    user_team = user.get("TEAM_CD", "")

    if action == "DELETE":
        del_flg = record.get("DEL_FLG", "")
        if del_flg not in ("", "N"):
            return False

    for row in role_rows:
        if (
            row.get("role_id", "") == role_id
            and row.get("object", "") == object
            and row.get("action", "") == action
        ):
            if role_id == "ADMIN":
                return True

            scope = row.get("scope", "")
            if scope == "ALL":
                return True
            if scope == "TEAM":
                return user_team == record.get("TEAM_CD", "")
            if scope == "OWN":
                return user_id == record.get("OWNER_UID", "")
            return False

    return False
